package rt

// BenchmarkConstMapLookup (M5-S4 and M22-S4, SPEC T-Sec9, Table T-PERF
// "lookup about 2.5ns versus about 14ns") reports lookup latency. It
// measures one const-map lookup against a runtime map of the same 1000 keys.
// "const" hashes each key inside the loop, as the generated lookup does;
// "const-probe" precomputes the base hashes, so it times the bucket read,
// slot probe, and key check alone. The table below is the output of the
// compiler's layout for those keys (cmd/compile/internal/logos/constmap.go,
// seed search budget 1000000), so the probe runs the shape generated code
// runs: one bucket read, one slot probe, one full-key comparison.
//
// The latency figures are a report; two properties are asserted. A lookup
// allocates nothing, over every key. And the table symbol of a 1,000-key
// const map, compiled by the logos command, is read-only data (type R in go
// tool nm), so a lookup reads memory the program cannot write and the
// garbage collector never scans. TestConstMapLookupZeroAlloc and
// TestConstMapTableReadOnly run the same checks without -bench.

import (
	"fmt"
	"internal/testenv"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// constBenchKeys returns the 1000 benchmark keys, in the order the table
// was generated from.
func constBenchKeys() []string {
	keys := make([]string, 1000)
	for i := range keys {
		keys[i] = fmt.Sprintf("k%05d", i)
	}
	return keys
}

var sinkConstMap int

func BenchmarkConstMapLookup(b *testing.B) {
	keys := constBenchKeys()
	rtMap := make(map[string]int, len(keys))
	for i, k := range keys {
		rtMap[k] = i
	}
	tab := constBenchTable()
	if n := lookupAllocs(tab, keys); n != 0 {
		b.Fatalf("const lookup allocates %v times over %d keys, want 0", n, len(keys))
	}
	b.Run("table-symbol", func(b *testing.B) {
		if sym := constTableSymbolType(b); sym != "R" {
			b.Fatalf("const map table symbol type = %q, want R (read-only data)", sym)
		}
	})
	b.Run("const", func(b *testing.B) {
		b.ReportAllocs()
		for i := range b.N {
			k := keys[i%len(keys)]
			v, ok := tab.Get(HashString(k), k)
			if ok {
				sinkConstMap += v
			}
		}
	})
	hashes := make([]uint64, len(keys))
	for i, k := range keys {
		hashes[i] = HashString(k)
	}
	b.Run("const-probe", func(b *testing.B) {
		b.ReportAllocs()
		for i := range b.N {
			j := i % len(keys)
			v, ok := tab.Get(hashes[j], keys[j])
			if ok {
				sinkConstMap += v
			}
		}
	})
	b.Run("runtime", func(b *testing.B) {
		b.ReportAllocs()
		for i := range b.N {
			v, ok := rtMap[keys[i%len(keys)]]
			if ok {
				sinkConstMap += v
			}
		}
	})
}

