// lookupAllocs returns the heap allocations that one pass of const lookups
// over keys performs.
func lookupAllocs(tab *ConstTable[string, int], keys []string) float64 {
	return testing.AllocsPerRun(10, func() {
		for _, k := range keys {
			v, ok := tab.Get(HashString(k), k)
			if ok {
				sinkConstMap += v
			}
		}
	})
}

