// constMapProbeSrc returns the loGo/s program whose binary the symbol check
// inspects: a const map of the 1000 benchmark keys, which lowers to a
// perfect-hash table because it has more than 8 keys.
func constMapProbeSrc() string {
	var b strings.Builder
	b.WriteString("package main\n\nimport \"fmt\"\n\nconst big = map[string]int{")
	for i, k := range constBenchKeys() {
		fmt.Fprintf(&b, "%q: %d, ", k, i)
	}
	b.WriteString("}\n\nfunc main() {\n\tfmt.Println(big[\"k00031\"] ?? -1)\n}\n")
	return b.String()
}

// constTableSymbolType compiles constMapProbeSrc with the logos command that
// sits beside the go tool, and returns the type letter go tool nm prints for
// the table symbol. A toolchain without the logos command skips the caller.
func constTableSymbolType(tb testing.TB) string {
	tb.Helper()
	testenv.MustHaveGoBuild(tb)
	goTool := testenv.GoToolPath(tb)
	logosTool := filepath.Join(filepath.Dir(goTool), "logos")
	if runtime.GOOS == "windows" {
		logosTool += ".exe"
	}
	if _, err := os.Stat(logosTool); err != nil {
		tb.Skipf("no logos command beside the go tool: %v", err)
	}
	dir := tb.TempDir()
	for name, text := range map[string]string{"go.mod": "module probe\n\ngo 1.27\n", "main.lgo": constMapProbeSrc()} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(text), 0o666); err != nil {
			tb.Fatal(err)
		}
	}
	env := append(os.Environ(), "GOFLAGS=", "GOPROXY=off", "GOTOOLCHAIN=local")
	build := testenv.Command(tb, logosTool, "build", "-o", "probe.exe", ".")
	build.Dir = dir
	build.Env = env
	if out, err := build.CombinedOutput(); err != nil {
		tb.Fatalf("logos build: %v\n%s", err, out)
	}
	nm := testenv.Command(tb, goTool, "tool", "nm", filepath.Join(dir, "probe.exe"))
	nm.Env = env
	out, err := nm.CombinedOutput()
	if err != nil {
		tb.Fatalf("go tool nm: %v\n%s", err, out)
	}
	for _, line := range strings.Split(string(out), "\n") {
		if f := strings.Fields(line); len(f) >= 3 && f[len(f)-1] == constTableSymbol {
			return f[len(f)-2]
		}
	}
	tb.Fatalf("go tool nm lists no symbol %s", constTableSymbol)
	return ""
}

// TestConstMapLookupZeroAlloc checks that a const lookup allocates nothing.
func TestConstMapLookupZeroAlloc(t *testing.T) {
	keys := constBenchKeys()
	if n := lookupAllocs(constBenchTable(), keys); n != 0 {
		t.Errorf("const lookup allocates %v times over %d keys, want 0", n, len(keys))
	}
}

// TestConstMapTableReadOnly checks that the lookup table of a 1,000-key const
// map lives in read-only data.
func TestConstMapTableReadOnly(t *testing.T) {
	if testing.Short() {
		t.Skip("builds a loGo/s program")
	}
	if sym := constTableSymbolType(t); sym != "R" {
		t.Errorf("%s has nm type %q, want R (read-only data)", constTableSymbol, sym)
	}
}

func TestConstBenchTable(t *testing.T) {
	keys := constBenchKeys()
	tab := constBenchTable()
	for i, k := range keys {
		v, ok := tab.Get(HashString(k), k)
		if !ok || v != i {
			t.Fatalf("Get(%q) = %d, %v; want %d, true", k, v, ok, i)
		}
	}
	if _, ok := tab.Get(HashString("absent"), "absent"); ok {
		t.Fatal("absent key found")
	}
}
